{"command": "cd /tmp && python3 -c "
import sys
with open('prefix_prefill.py', 'r') as f:
    lines = f.readlines()
inside = False
kernel_lines = []
for line in lines:
    if line.startswith('@triton.jit'):
        if inside:
            break
        inside = True
        kernel_lines.append(line)
        continue
    if inside:
        kernel_lines.append(line)
        if line.startswith('def _fwd_kernel_alibi'):
            break
sys.stdout.write(''.join(kernel_lines))
" > kernel1.txt"}

